# Validation
def validate_topic_set(topics, name):
    assert len(topics) == 100, f"Expected 100 {name} topics, got {len(topics)}"
    seen_titles = set()
    for item in topics:
        assert len(item) == 6, f"Topic tuple must have 6 elements: {item}"
        title, subj, sys_name, hallmark, ref_label, cit_url = item
        assert title not in seen_titles, f"Duplicate topic title in {name}: {title}"
        seen_titles.add(title)
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {name}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {name}: {title}"
        assert len(hallmark) >= 30, f"Hallmark too short in {name}: {hallmark}"
        assert len(ref_label) >= 5, f"Reference label too short in {name}: {ref_label}"
        assert cit_url.startswith("https://"), f"Invalid citation URL in {name}: {cit_url}"
    print(f"Validated 100 {name} topics successfully.")

# Read base HAAD/DHA
from build_mega50_b import HAAD_DHA_RAW as haad_base
full_haad = haad_base + haad_remaining

validate_topic_set(full_haad, "HAAD / DHA")
validate_topic_set(plab_topics, "PLAB / UKMLA")
validate_topic_set(amc_topics, "AMC")

# Write to mega50_topics_b.py
out_file = os.path.join(os.path.dirname(__file__), "mega50_topics_b.py")
with open(out_file, "w", encoding="utf-8") as f:
    f.write('"""Generated topics for Mega-Batch 50 Part B (HAAD / DHA, PLAB / UKMLA, AMC)"""\n\n')
    f.write(f"HAAD_DHA_TOPICS = {repr(full_haad)}\n\n")
    f.write(f"PLAB_TOPICS = {repr(plab_topics)}\n\n")
    f.write(f"AMC_TOPICS = {repr(amc_topics)}\n\n")

print(f"Wrote {out_file} successfully.")
